// Verification Testbench for Design A, Design B, and Design C
// Compares all 3 hardware designs against test vectors generated by Python reference oracle.

`timescale 1ns/1ps

module tb_dot_product;

    parameter N = 64;
    parameter ACC_WIDTH = 32;

    reg  [N*8-1:0] X_flat;
    reg  [N*8-1:0] Wa_flat;
    reg  [N*2-1:0] Wb_flat;
    reg  [N-1:0]   Wc_mask;
    reg  [N-1:0]   Wc_sign;

    wire signed [ACC_WIDTH-1:0] Ya;
    wire signed [ACC_WIDTH-1:0] Yb;
    wire signed [ACC_WIDTH-1:0] Yc;

    // Instantiate Design A
    design_a_general_mac #(
        .N(N),
        .ACC_WIDTH(ACC_WIDTH)
    ) dut_a (
        .X_flat(X_flat),
        .W_flat(Wa_flat),
        .Y(Ya)
    );

    // Instantiate Design B
    design_b_optimized_binary #(
        .N(N),
        .ACC_WIDTH(ACC_WIDTH)
    ) dut_b (
        .X_flat(X_flat),
        .W_flat(Wb_flat),
        .Y(Yb)
    );

    // Instantiate Design C
    design_c_ht1_ternary #(
        .N(N),
        .ACC_WIDTH(ACC_WIDTH)
    ) dut_c (
        .X_flat(X_flat),
        .W_mask(Wc_mask),
        .W_sign(Wc_sign),
        .Y(Yc)
    );

    // Helper task to drive single vector test
    integer err_count = 0;
    integer test_count = 0;

    task verify_vector;
        input signed [ACC_WIDTH-1:0] expected_y;
        begin
            #1; // Allow combinational propagation
            test_count = test_count + 1;
            if (Ya !== expected_y || Yb !== expected_y || Yc !== expected_y) begin
                $display("ERROR at Test %0d: Expected=%0d | Design A=%0d | Design B=%0d | Design C=%0d",
                         test_count, expected_y, Ya, Yb, Yc);
                err_count = err_count + 1;
            end
        end
    endtask

    // File I/O for external Python vector execution
    integer file_in, r;
    reg signed [31:0] expected_val;
    reg signed [7:0]  w_val;
    reg signed [7:0]  x_val;
    integer idx;

    initial begin
        file_in = $fopen("test_vectors.txt", "r");
        if (file_in == 0) begin
            $display("ERROR: Could not open test_vectors.txt");
            $finish;
        end

        err_count = 0;
        test_count = 0;

        while (!$feof(file_in)) begin
            // Read expected output Y
            r = $fscanf(file_in, "%d\n", expected_val);
            if (r == 1) begin
                // Read N weight/activation pairs
                for (idx = 0; idx < N; idx = idx + 1) begin
                    r = $fscanf(file_in, "%d %d\n", w_val, x_val);
                    X_flat[idx*8 +: 8] = x_val;
                    Wa_flat[idx*8 +: 8] = w_val;

                    if (w_val == 0) begin
                        Wb_flat[idx*2 +: 2] = 2'b00;
                        Wc_mask[idx] = 1'b0;
                        Wc_sign[idx] = 1'b0;
                    end else if (w_val == 1) begin
                        Wb_flat[idx*2 +: 2] = 2'b01;
                        Wc_mask[idx] = 1'b1;
                        Wc_sign[idx] = 1'b0;
                    end else if (w_val == -1) begin
                        Wb_flat[idx*2 +: 2] = 2'b11;
                        Wc_mask[idx] = 1'b1;
                        Wc_sign[idx] = 1'b1;
                    end
                end
                verify_vector(expected_val);
            end
        end

        $fclose(file_in);
        $display("VERIFICATION COMPLETE: %0d tests executed, %0d errors.", test_count, err_count);
        if (err_count > 0) $fatal(1, "Verification failed!");
        $finish;
    end

endmodule
